const request = $json;

const now = new Date();
const timestamp = now.getTime();

// Generate a lightweight unique suffix without external modules
const randomPart = Math.random()
  .toString(36)
  .substring(2, 10)
  .toUpperCase();

const requestId = `REQ-${timestamp}-${randomPart}`;

const correlationId = `CORR-${timestamp}-${randomPart}`;

return {
  json: {
    ...request,

    request_id: requestId,
    correlation_id: correlationId,

    workflow_stage: 'request_intake',

    processing_started_at: now.toISOString(),

    retry_count: 0,

    schema_version: '1.0'
  }
};

const request = $json;

const errors = [];
const warnings = [];

// -----------------------------------------
// Helper: validate required string fields
// -----------------------------------------
function validateString(field, options = {}) {
  const {
    required = true,
    minLength = 1,
    maxLength = 500
  } = options;

  const value = request[field];

  if (required && (value === undefined || value === null || value === '')) {
    errors.push({
      field,
      code: 'REQUIRED_FIELD_MISSING',
      message: `${field} is required`
    });
    return;
  }

  if (value !== undefined && value !== null) {
    if (typeof value !== 'string') {
      errors.push({
        field,
        code: 'INVALID_TYPE',
        message: `${field} must be a string`
      });
      return;
    }

    const trimmed = value.trim();

    if (required && trimmed.length < minLength) {
      errors.push({
        field,
        code: 'INVALID_LENGTH',
        message: `${field} is too short`
      });
    }

    if (trimmed.length > maxLength) {
      errors.push({
        field,
        code: 'MAX_LENGTH_EXCEEDED',
        message: `${field} exceeds ${maxLength} characters`
      });
    }
  }
}


// -----------------------------------------
// Required request fields
// -----------------------------------------
validateString('channel', { maxLength: 50 });
validateString('requester_id', { maxLength: 100 });
validateString('requester_name', { maxLength: 150 });
validateString('question', { minLength: 3, maxLength: 1000 });
validateString('source', { maxLength: 100 });
validateString('received_at', { maxLength: 100 });
validateString('environment', { maxLength: 50 });
validateString('status', { maxLength: 50 });

validateString('request_id', { maxLength: 150 });
validateString('correlation_id', { maxLength: 150 });
validateString('workflow_stage', { maxLength: 100 });
validateString('processing_started_at', { maxLength: 100 });
validateString('schema_version', { maxLength: 20 });


// -----------------------------------------
// Allowed request channels
// -----------------------------------------
const allowedChannels = [
  'manual',
  'slack',
  'form',
  'webhook',
  'api',
  'scheduled'
];

if (
  typeof request.channel === 'string' &&
  !allowedChannels.includes(request.channel)
) {
  errors.push({
    field: 'channel',
    code: 'UNSUPPORTED_CHANNEL',
    message: `Unsupported request channel: ${request.channel}`
  });
}


// -----------------------------------------
// Allowed environments
// -----------------------------------------
const allowedEnvironments = [
  'development',
  'staging',
  'production'
];

if (
  typeof request.environment === 'string' &&
  !allowedEnvironments.includes(request.environment)
) {
  errors.push({
    field: 'environment',
    code: 'INVALID_ENVIRONMENT',
    message: `Unsupported environment: ${request.environment}`
  });
}


// -----------------------------------------
// Expected initial request status
// -----------------------------------------
if (
  typeof request.status === 'string' &&
  request.status !== 'received'
) {
  errors.push({
    field: 'status',
    code: 'INVALID_REQUEST_STATUS',
    message: 'Initial request status must be received'
  });
}


// -----------------------------------------
// Validate timestamps
// -----------------------------------------
function validateTimestamp(field) {
  const value = request[field];

  if (typeof value === 'string') {
    const parsed = Date.parse(value);

    if (Number.isNaN(parsed)) {
      errors.push({
        field,
        code: 'INVALID_TIMESTAMP',
        message: `${field} must contain a valid ISO timestamp`
      });
    }
  }
}

validateTimestamp('received_at');
validateTimestamp('processing_started_at');


// -----------------------------------------
// Validate trace IDs
// -----------------------------------------
if (
  typeof request.request_id === 'string' &&
  !request.request_id.startsWith('REQ-')
) {
  errors.push({
    field: 'request_id',
    code: 'INVALID_REQUEST_ID',
    message: 'request_id must start with REQ-'
  });
}

if (
  typeof request.correlation_id === 'string' &&
  !request.correlation_id.startsWith('CORR-')
) {
  errors.push({
    field: 'correlation_id',
    code: 'INVALID_CORRELATION_ID',
    message: 'correlation_id must start with CORR-'
  });
}


// -----------------------------------------
// Validate retry count
// -----------------------------------------
if (
  !Number.isInteger(request.retry_count) ||
  request.retry_count < 0
) {
  errors.push({
    field: 'retry_count',
    code: 'INVALID_RETRY_COUNT',
    message: 'retry_count must be a non-negative integer'
  });
}


// -----------------------------------------
// Optional warning checks
// -----------------------------------------
if (
  typeof request.question === 'string' &&
  request.question.trim().length > 0 &&
  request.question.trim().length < 10
) {
  warnings.push({
    field: 'question',
    code: 'SHORT_QUESTION',
    message: 'The reporting question may require clarification'
  });
}


// -----------------------------------------
// Final validation result
// -----------------------------------------
const isValid = errors.length === 0;

return {
  json: {
    ...request,

    workflow_stage: 'request_validation',

    validation_status: isValid
      ? 'valid'
      : 'rejected',

    validation: {
      is_valid: isValid,
      error_count: errors.length,
      warning_count: warnings.length,
      errors,
      warnings,
      validated_at: new Date().toISOString(),
      validation_version: '1.0'
    }
  }
};

