const data = $json;

const intent = data.parsed_intent ?? {};
const requestedMetrics = Array.isArray(intent.metrics)
  ? intent.metrics
  : [];

const catalogueMatches = Array.isArray(data.metric_catalogue_matches)
  ? data.metric_catalogue_matches
  : [];

const dimensions = Array.isArray(intent.dimensions)
  ? intent.dimensions
  : [];

const filters = Array.isArray(intent.filters)
  ? intent.filters
  : [];

const errors = [];
const warnings = [];

// --------------------------------------------------
// 1. Validate supported reporting intent
// --------------------------------------------------

const reportIntents = [
  'metric_report',
  'breakdown_report',
  'trend_report',
  'comparison_report',
  'data_quality_report'
];

if (intent.intent === 'unsupported') {
  errors.push({
    field: 'intent',
    code: 'UNSUPPORTED_REPORTING_INTENT',
    message: 'The request is not supported by the governed reporting system'
  });
}

if (
  intent.intent !== 'unsupported' &&
  !reportIntents.includes(intent.intent)
) {
  errors.push({
    field: 'intent',
    code: 'INVALID_REPORTING_INTENT',
    message: `Unsupported intent: ${intent.intent}`
  });
}

// --------------------------------------------------
// 2. Metrics must exist
// --------------------------------------------------

if (
  reportIntents.includes(intent.intent) &&
  requestedMetrics.length === 0
) {
  errors.push({
    field: 'metrics',
    code: 'METRIC_REQUIRED',
    message: 'At least one reporting metric is required'
  });
}

// Prevent duplicate metric requests.
const uniqueRequestedMetrics = [...new Set(requestedMetrics)];

if (uniqueRequestedMetrics.length !== requestedMetrics.length) {
  errors.push({
    field: 'metrics',
    code: 'DUPLICATE_METRIC',
    message: 'The same metric cannot be requested more than once'
  });
}

// --------------------------------------------------
// 3. Build deterministic catalogue lookup
// --------------------------------------------------

const catalogueByKey = new Map();

for (const metric of catalogueMatches) {
  if (
    metric &&
    typeof metric.metric_key === 'string' &&
    !catalogueByKey.has(metric.metric_key)
  ) {
    catalogueByKey.set(metric.metric_key, metric);
  }
}

// --------------------------------------------------
// 4. Check metric existence and activation
// --------------------------------------------------

for (const metricKey of uniqueRequestedMetrics) {
  const metric = catalogueByKey.get(metricKey);

  if (!metric) {
    errors.push({
      field: 'metrics',
      code: 'METRIC_NOT_APPROVED',
      message: `Metric is not present in the approved catalogue: ${metricKey}`,
      metric_key: metricKey
    });
    continue;
  }

  if (metric.is_active !== true) {
    errors.push({
      field: 'metrics',
      code: 'METRIC_INACTIVE',
      message: `Metric is currently inactive: ${metricKey}`,
      metric_key: metricKey
    });
  }

  if (
    typeof metric.query_key !== 'string' ||
    metric.query_key.trim() === ''
  ) {
    errors.push({
      field: 'query_key',
      code: 'APPROVED_QUERY_KEY_MISSING',
      message: `Metric does not have an approved query key: ${metricKey}`,
      metric_key: metricKey
    });
  }
}

// --------------------------------------------------
// 5. Validate requested dimensions
// --------------------------------------------------

for (const dimension of dimensions) {
  for (const metricKey of uniqueRequestedMetrics) {
    const metric = catalogueByKey.get(metricKey);

    if (!metric || metric.is_active !== true) {
      continue;
    }

    const allowedDimensions =
      Array.isArray(metric.allowed_dimensions)
        ? metric.allowed_dimensions
        : [];

    if (!allowedDimensions.includes(dimension)) {
      errors.push({
        field: 'dimensions',
        code: 'DIMENSION_NOT_ALLOWED',
        message:
          `Dimension ${dimension} is not allowed for metric ${metricKey}`,
        metric_key: metricKey,
        dimension
      });
    }
  }
}

// --------------------------------------------------
// 6. Validate filter fields
// --------------------------------------------------

const allowedOperators = new Set([
  'eq',
  'neq',
  'in',
  'not_in',
  'gt',
  'gte',
  'lt',
  'lte',
  'contains',
  'not_contains',
  'is_null',
  'is_not_null'
]);

for (const filter of filters) {
  const field = filter?.field;
  const operator = filter?.operator;

  if (typeof field !== 'string' || field.trim() === '') {
    errors.push({
      field: 'filters',
      code: 'INVALID_FILTER_FIELD',
      message: 'Every filter must contain a valid field'
    });

    continue;
  }

  if (
    typeof operator !== 'string' ||
    !allowedOperators.has(operator)
  ) {
    errors.push({
      field: 'filters',
      code: 'FILTER_OPERATOR_NOT_ALLOWED',
      message: `Unsupported filter operator: ${operator}`,
      filter_field: field
    });
  }

  for (const metricKey of uniqueRequestedMetrics) {
    const metric = catalogueByKey.get(metricKey);

    if (!metric || metric.is_active !== true) {
      continue;
    }

    const allowedFilters =
      Array.isArray(metric.allowed_filters)
        ? metric.allowed_filters
        : [];

    if (!allowedFilters.includes(field)) {
      errors.push({
        field: 'filters',
        code: 'FILTER_NOT_ALLOWED',
        message:
          `Filter ${field} is not allowed for metric ${metricKey}`,
        metric_key: metricKey,
        filter_field: field
      });
    }
  }
}

// --------------------------------------------------
// 7. Validate relative date-range governance
// --------------------------------------------------

const relativeDateSpan = {
  today: 1,
  yesterday: 1,
  this_week: 7,
  last_week: 7,
  this_month: 31,
  last_month: 31,
  this_quarter: 92,
  last_quarter: 92,
  this_year: 366,
  last_year: 366
};

const dateRange = intent.date_range ?? {};

if (dateRange.type === 'relative') {
  const requestedSpan =
    relativeDateSpan[dateRange.value];

  if (!requestedSpan) {
    errors.push({
      field: 'date_range',
      code: 'UNSUPPORTED_RELATIVE_DATE_RANGE',
      message:
        `Unsupported relative date range: ${dateRange.value}`
    });
  } else {
    for (const metricKey of uniqueRequestedMetrics) {
      const metric = catalogueByKey.get(metricKey);

      if (!metric || metric.is_active !== true) {
        continue;
      }

      if (metric.maximum_date_range) {
        const maximumSpan =
          relativeDateSpan[metric.maximum_date_range];

        if (!maximumSpan) {
          errors.push({
            field: 'maximum_date_range',
            code: 'INVALID_CATALOGUE_DATE_LIMIT',
            message:
              `Catalogue contains an invalid date limit for ${metricKey}`,
            metric_key: metricKey
          });
        } else if (requestedSpan > maximumSpan) {
          errors.push({
            field: 'date_range',
            code: 'DATE_RANGE_EXCEEDS_LIMIT',
            message:
              `Requested date range exceeds the maximum allowed range for ${metricKey}`,
            metric_key: metricKey,
            requested: dateRange.value,
            maximum: metric.maximum_date_range
          });
        }
      }
    }
  }
}

if (dateRange.type === 'unspecified') {
  warnings.push({
    field: 'date_range',
    code: 'DATE_RANGE_NOT_SPECIFIED',
    message:
      'The approved metric default date range will be used'
  });
}

// Fail closed until absolute-date parsing is implemented.
if (dateRange.type === 'absolute') {
  errors.push({
    field: 'date_range',
    code: 'ABSOLUTE_DATE_RANGE_NOT_ENABLED',
    message:
      'Absolute date ranges are not enabled in the current governance version'
  });
}

// --------------------------------------------------
// 8. Validate comparison requirements
// --------------------------------------------------

for (const metricKey of uniqueRequestedMetrics) {
  const metric = catalogueByKey.get(metricKey);

  if (!metric || metric.is_active !== true) {
    continue;
  }

  if (
    metric.requires_comparison === true &&
    intent.comparison === null
  ) {
    errors.push({
      field: 'comparison',
      code: 'COMPARISON_REQUIRED',
      message:
        `Metric ${metricKey} requires a comparison`,
      metric_key: metricKey
    });
  }
}

if (
  intent.intent === 'comparison_report' &&
  intent.comparison === null
) {
  errors.push({
    field: 'comparison',
    code: 'COMPARISON_MISSING',
    message:
      'comparison_report requires comparison instructions'
  });
}

// --------------------------------------------------
// Final result
// --------------------------------------------------

const isValid = errors.length === 0;

return {
  json: {
    ...data,

    workflow_stage: 'metric_governance_validation',

    governance_validation: {
      is_valid: isValid,
      validation_status: isValid
        ? 'approved'
        : 'rejected',

      error_count: errors.length,
      warning_count: warnings.length,

      errors,
      warnings,

      validated_metric_keys:
        uniqueRequestedMetrics.filter(
          key =>
            catalogueByKey.has(key) &&
            catalogueByKey.get(key)?.is_active === true
        ),

      validated_at: new Date().toISOString(),
      validation_version: '1.0'
    }
  }
};

// REVINT Phase 4 / Phase 9
// VAL | Validate Approved Query
//
// Purpose:
// Validate that the SQL template resolved from control.query_templates
// is the exact template authorized by the already-approved metric.
//
// Phase 9 hardening:
// A manager-requested business filter must be allowed by the metric
// AND executable by the selected query template.
//
// This node DOES NOT execute SQL.

const template = $json;

// Recover the governed request context from the approved path.
// The Postgres resolver intentionally returns only template data,
// so we reconnect it here to the already-approved request context.
const context = $('AUD | Log Governance Approved').item.json;

const errors = [];
const warnings = [];

const governance = context.governance_validation ?? {};
const parsedIntent = context.parsed_intent ?? {};

const catalogueMatches = Array.isArray(context.metric_catalogue_matches)
	? context.metric_catalogue_matches
	: [];

// ---------------------------------------------------------
// 1. Previous governance approval must exist
// ---------------------------------------------------------

if (governance.is_valid !== true) {
	errors.push({
		code: 'GOVERNANCE_NOT_APPROVED',
		field: 'governance_validation',
		message: 'Reporting query execution requires prior governance approval',
	});
}

// ---------------------------------------------------------
// 2. Phase 4 v1 allows one metric/query per execution
// ---------------------------------------------------------

if (catalogueMatches.length === 0) {
	errors.push({
		code: 'APPROVED_METRIC_NOT_FOUND',
		field: 'metric_catalogue_matches',
		message: 'No governance-approved metric was available for query resolution',
	});
}

if (catalogueMatches.length > 1) {
	errors.push({
		code: 'MULTI_METRIC_QUERY_NOT_ENABLED',
		field: 'metric_catalogue_matches',
		message: 'Multi-metric query execution is not enabled in the current query-engine version',
	});
}

const approvedMetric = catalogueMatches[0] ?? null;

const expectedQueryKey =
	typeof approvedMetric?.query_key === 'string'
		? approvedMetric.query_key.trim()
		: '';

// ---------------------------------------------------------
// 3. Approved metric must contain a query_key
// ---------------------------------------------------------

if (!expectedQueryKey) {
	errors.push({
		code: 'APPROVED_QUERY_KEY_MISSING',
		field: 'query_key',
		message: 'The governance-approved metric does not contain a query_key',
	});
}

// ---------------------------------------------------------
// 4. Resolver must actually return a template
// ---------------------------------------------------------

const resolvedQueryKey =
	typeof template?.query_key === 'string'
		? template.query_key.trim()
		: '';

if (!resolvedQueryKey) {
	const missingTemplateError = {
		code: 'QUERY_TEMPLATE_NOT_FOUND',
		field: 'query_key',
		message: `No active approved query template was resolved for query_key ${expectedQueryKey || 'unknown'}`,
		expected_query_key: expectedQueryKey || null,
	};

	return {
		...context,

		resolved_query: {
			query_key: null,
			query_name: null,
			description: null,
			sql_template: null,
			allowed_parameters: [],
			result_type: null,
			maximum_rows: null,
			is_active: false,
			version: null,
		},

		query_validation: {
			is_valid: false,
			validation_status: 'rejected',

			errors: [missingTemplateError],
			warnings: [],

			error_count: 1,
			warning_count: 0,

			expected_query_key: expectedQueryKey || null,
			resolved_query_key: null,

			validation_version: '1.1',
			validated_at: new Date().toISOString(),
		},

		workflow_stage: 'query_rejected',
	};
}

// ---------------------------------------------------------
// 5. Resolved query must match the governed query exactly
// ---------------------------------------------------------

if (
	expectedQueryKey &&
	resolvedQueryKey &&
	expectedQueryKey !== resolvedQueryKey
) {
	errors.push({
		code: 'QUERY_KEY_MISMATCH',
		field: 'query_key',
		message: `Resolved query_key ${resolvedQueryKey} does not match governance-approved query_key ${expectedQueryKey}`,
		expected_query_key: expectedQueryKey,
		resolved_query_key: resolvedQueryKey,
	});
}

// ---------------------------------------------------------
// 6. Template must be active
// ---------------------------------------------------------

if (template?.is_active !== true) {
	errors.push({
		code: 'QUERY_TEMPLATE_INACTIVE',
		field: 'is_active',
		message: 'Resolved query template is not active',
	});
}

// ---------------------------------------------------------
// 7. SQL template must exist
// ---------------------------------------------------------

const sqlTemplate =
	typeof template?.sql_template === 'string'
		? template.sql_template.trim()
		: '';

if (!sqlTemplate) {
	errors.push({
		code: 'SQL_TEMPLATE_MISSING',
		field: 'sql_template',
		message: 'Resolved query template does not contain SQL',
	});
}

// ---------------------------------------------------------
// 8. SQL must remain read-only
// ---------------------------------------------------------

if (sqlTemplate) {
	const normalizedSql = sqlTemplate
		.replace(/;\s*$/, '')
		.trim();

	if (!/^(SELECT|WITH)\b/i.test(normalizedSql)) {
		errors.push({
			code: 'SQL_NOT_READ_ONLY',
			field: 'sql_template',
			message: 'Approved reporting SQL must begin with SELECT or WITH',
		});
	}

	const forbiddenSql =
		/\b(INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|CREATE|GRANT|REVOKE|COPY|CALL|DO|EXECUTE)\b/i;

	if (forbiddenSql.test(normalizedSql)) {
		errors.push({
			code: 'FORBIDDEN_SQL_OPERATION',
			field: 'sql_template',
			message: 'Approved reporting SQL contains a forbidden database operation',
		});
	}

	if (
		normalizedSql.includes('--') ||
		normalizedSql.includes('/*') ||
		normalizedSql.includes('*/')
	) {
		errors.push({
			code: 'SQL_COMMENTS_NOT_ALLOWED',
			field: 'sql_template',
			message: 'SQL comments are not allowed in approved runtime templates',
		});
	}

	if (normalizedSql.includes(';')) {
		errors.push({
			code: 'MULTIPLE_SQL_STATEMENTS_NOT_ALLOWED',
			field: 'sql_template',
			message: 'Approved runtime templates must contain exactly one SQL statement',
		});
	}

	if (/\b(control|audit)\s*\./i.test(normalizedSql)) {
		errors.push({
			code: 'FORBIDDEN_SCHEMA_REFERENCE',
			field: 'sql_template',
			message: 'Reporting SQL may not access control or audit schemas',
		});
	}
}

// ---------------------------------------------------------
// 9. Validate allowed runtime parameters
// ---------------------------------------------------------

const allowedParameters = Array.isArray(template?.allowed_parameters)
	? template.allowed_parameters
	: null;

if (!allowedParameters) {
	errors.push({
		code: 'QUERY_PARAMETERS_INVALID',
		field: 'allowed_parameters',
		message: 'allowed_parameters must be an array',
	});
}

const supportedRuntimeParameters = new Set([
	'start_at',
	'end_at',
]);

const normalizedAllowedParameters = [];

if (allowedParameters) {
	const seen = new Set();

	for (const parameter of allowedParameters) {
		if (
			typeof parameter !== 'string' ||
			!parameter.trim()
		) {
			errors.push({
				code: 'QUERY_PARAMETER_INVALID',
				field: 'allowed_parameters',
				message: 'Every allowed query parameter must be a non-empty string',
			});

			continue;
		}

		const normalizedParameter = parameter.trim();

		normalizedAllowedParameters.push(normalizedParameter);

		if (seen.has(normalizedParameter)) {
			errors.push({
				code: 'DUPLICATE_QUERY_PARAMETER',
				field: 'allowed_parameters',
				message: `Duplicate query parameter: ${normalizedParameter}`,
				parameter: normalizedParameter,
			});
		}

		seen.add(normalizedParameter);

		if (!supportedRuntimeParameters.has(normalizedParameter)) {
			errors.push({
				code: 'QUERY_PARAMETER_NOT_SUPPORTED',
				field: 'allowed_parameters',
				message: `Runtime parameter ${normalizedParameter} is not enabled in the current query-engine version`,
				parameter: normalizedParameter,
			});
		}
	}
}

// ---------------------------------------------------------
// 10. Cross-contract filter executability validation
// ---------------------------------------------------------

const requestedFilters = Array.isArray(parsedIntent.filters)
	? parsedIntent.filters
	: [];

const metricAllowedFilters = Array.isArray(approvedMetric?.allowed_filters)
	? approvedMetric.allowed_filters
		.filter(
			(value) =>
				typeof value === 'string' &&
				value.trim()
		)
		.map((value) => value.trim())
	: [];

// Phase 4 v1 convention:
// A business filter is executable only when the selected query template
// explicitly declares a parameter with the same governed field name.
//
// Current approved templates declare start_at/end_at only, therefore
// requested business filters fail closed instead of being silently ignored.

const dateParameters = new Set([
	'start_at',
	'end_at',
]);

const executableTemplateFilters =
	normalizedAllowedParameters.filter(
		(parameter) => !dateParameters.has(parameter)
	);

for (let index = 0; index < requestedFilters.length; index++) {
	const filter = requestedFilters[index];

	if (
		!filter ||
		typeof filter !== 'object' ||
		Array.isArray(filter)
	) {
		errors.push({
			code: 'FILTER_CONTRACT_INVALID',
			field: `parsed_intent.filters[${index}]`,
			message: 'Every requested filter must be a structured filter object',
		});

		continue;
	}

	const filterField =
		typeof filter.field === 'string'
			? filter.field.trim()
			: '';

	if (!filterField) {
		errors.push({
			code: 'FILTER_FIELD_MISSING',
			field: `parsed_intent.filters[${index}].field`,
			message: 'Requested filter does not contain a valid field name',
		});

		continue;
	}

	// Defense in depth:
	// governance should already enforce this,
	// but query authorization checks it again.
	if (!metricAllowedFilters.includes(filterField)) {
		errors.push({
			code: 'FILTER_NOT_ALLOWED_BY_METRIC',
			field: `parsed_intent.filters[${index}].field`,
			message: `Filter ${filterField} is not allowed by the governance-approved metric`,
			filter_field: filterField,
		});

		continue;
	}

	// Critical Phase 9 control:
	// never silently drop an approved metric filter if the SQL template
	// has no executable parameter contract for it.
	if (!executableTemplateFilters.includes(filterField)) {
		errors.push({
			code: 'FILTER_NOT_EXECUTABLE_BY_TEMPLATE',
			field: `parsed_intent.filters[${index}].field`,
			message: `Filter ${filterField} is allowed by the metric but is not executable by query template ${resolvedQueryKey}`,
			filter_field: filterField,
			query_key: resolvedQueryKey,
		});
	}
}

// ---------------------------------------------------------
// 11. Validate result type
// ---------------------------------------------------------

const approvedResultTypes = new Set([
	'scalar',
	'breakdown',
	'trend',
	'comparison',
	'data_quality',
]);

if (!approvedResultTypes.has(template?.result_type)) {
	errors.push({
		code: 'RESULT_TYPE_NOT_ALLOWED',
		field: 'result_type',
		message: `Unsupported query result type: ${template?.result_type ?? 'missing'}`,
	});
}

// ---------------------------------------------------------
// 12. Validate row limit
// ---------------------------------------------------------

const maximumRows = Number(template?.maximum_rows);

if (
	!Number.isInteger(maximumRows) ||
	maximumRows < 1 ||
	maximumRows > 10000
) {
	errors.push({
		code: 'QUERY_ROW_LIMIT_INVALID',
		field: 'maximum_rows',
		message: 'maximum_rows must be an integer between 1 and 10000',
	});
}

const metricMaximumRows = Number(approvedMetric?.maximum_rows);

if (
	Number.isInteger(maximumRows) &&
	Number.isInteger(metricMaximumRows) &&
	maximumRows > metricMaximumRows
) {
	errors.push({
		code: 'QUERY_ROW_LIMIT_EXCEEDS_METRIC_POLICY',
		field: 'maximum_rows',
		message: `Query maximum_rows ${maximumRows} exceeds metric policy maximum_rows ${metricMaximumRows}`,
	});
}

// ---------------------------------------------------------
// Final deterministic validation result
// ---------------------------------------------------------

const isValid = errors.length === 0;

return {
	...context,

	resolved_query: {
		query_key: resolvedQueryKey || null,
		query_name: template?.query_name ?? null,
		description: template?.description ?? null,
		sql_template: sqlTemplate || null,
		allowed_parameters: allowedParameters ?? [],
		result_type: template?.result_type ?? null,
		maximum_rows:
			Number.isFinite(maximumRows)
				? maximumRows
				: null,
		is_active: template?.is_active ?? false,
		version: template?.version ?? null,
	},

	query_validation: {
		is_valid: isValid,

		validation_status: isValid
			? 'approved'
			: 'rejected',

		errors,
		warnings,

		error_count: errors.length,
		warning_count: warnings.length,

		expected_query_key: expectedQueryKey || null,
		resolved_query_key: resolvedQueryKey || null,

		filter_contract: {
			requested_filter_count: requestedFilters.length,
			requested_filter_fields: requestedFilters
				.map((filter) =>
					typeof filter?.field === 'string'
						? filter.field.trim()
						: null
				)
				.filter(Boolean),

			metric_allowed_filters: metricAllowedFilters,
			template_executable_filters: executableTemplateFilters,
		},

		validation_version: '1.1',
		validated_at: new Date().toISOString(),
	},

	workflow_stage: isValid
		? 'query_approved'
		: 'query_rejected',
};

// REVINT Phase 4
// SQL | Build Runtime Parameters
//
// Purpose:
// Convert an already-governed reporting date request into
// deterministic parameter values for an approved SQL template.
//
// This node DOES NOT generate SQL.
// This node DOES NOT execute SQL.

const data = $json;

const errors = [];
const warnings = [];

const parsedIntent = data.parsed_intent ?? {};
const metric = Array.isArray(data.metric_catalogue_matches)
	? data.metric_catalogue_matches[0]
	: null;

const resolvedQuery = data.resolved_query ?? {};
const queryValidation = data.query_validation ?? {};

const allowedParameters = Array.isArray(
	resolvedQuery.allowed_parameters
)
	? resolvedQuery.allowed_parameters
	: [];

// ---------------------------------------------------------
// 1. Query must already be approved
// ---------------------------------------------------------

if (queryValidation.is_valid !== true) {
	errors.push({
		code: 'QUERY_NOT_APPROVED',
		field: 'query_validation',
		message: 'Runtime parameters cannot be built for an unapproved query',
	});
}

// ---------------------------------------------------------
// 2. Phase 4 v1 parameter contract
// ---------------------------------------------------------

const supportedParameters = new Set([
	'start_at',
	'end_at',
]);

for (const parameter of allowedParameters) {
	if (!supportedParameters.has(parameter)) {
		errors.push({
			code: 'RUNTIME_PARAMETER_NOT_SUPPORTED',
			field: 'allowed_parameters',
			message: `Runtime parameter ${parameter} is not supported`,
			parameter,
		});
	}
}

// Date-based templates in v1 must use start/end together.

const requiresStart = allowedParameters.includes('start_at');
const requiresEnd = allowedParameters.includes('end_at');

if (requiresStart !== requiresEnd) {
	errors.push({
		code: 'DATE_PARAMETER_PAIR_INVALID',
		field: 'allowed_parameters',
		message: 'Date-based templates must use both start_at and end_at',
	});
}

// ---------------------------------------------------------
// 3. Determine effective reporting date range
// ---------------------------------------------------------

const requestedDateRange = parsedIntent.date_range ?? {
	type: 'unspecified',
	value: '',
};

let effectiveRange = null;
let rangeSource = null;

if (requestedDateRange.type === 'relative') {
	effectiveRange =
		typeof requestedDateRange.value === 'string'
			? requestedDateRange.value.trim()
			: '';

	rangeSource = 'manager_request';
}

else if (requestedDateRange.type === 'unspecified') {
	effectiveRange =
		typeof metric?.default_date_range === 'string'
			? metric.default_date_range.trim()
			: '';

	rangeSource = 'metric_default';

	warnings.push({
		code: 'DEFAULT_DATE_RANGE_APPLIED',
		field: 'date_range',
		message: `No reporting period was supplied. Metric default ${effectiveRange || 'missing'} was applied.`,
	});
}

else {
	errors.push({
		code: 'DATE_RANGE_TYPE_NOT_EXECUTABLE',
		field: 'date_range',
		message: `Date range type ${requestedDateRange.type ?? 'missing'} is not enabled for execution`,
	});
}

// ---------------------------------------------------------
// 4. UTC date-boundary helpers
// ---------------------------------------------------------

const DAY_MS = 24 * 60 * 60 * 1000;

function utcStartOfDay(date) {
	return new Date(
		Date.UTC(
			date.getUTCFullYear(),
			date.getUTCMonth(),
			date.getUTCDate(),
			0,
			0,
			0,
			0
		)
	);
}

function addDays(date, days) {
	return new Date(date.getTime() + days * DAY_MS);
}

function monthStart(year, month) {
	return new Date(Date.UTC(year, month, 1, 0, 0, 0, 0));
}

function yearStart(year) {
	return new Date(Date.UTC(year, 0, 1, 0, 0, 0, 0));
}

function resolveRelativeRange(value, now) {
	const today = utcStartOfDay(now);

	const year = today.getUTCFullYear();
	const month = today.getUTCMonth();

	const dayOfWeek = today.getUTCDay();

	// ISO-style week: Monday = first day.
	const daysSinceMonday = (dayOfWeek + 6) % 7;

	const thisWeekStart = addDays(
		today,
		-daysSinceMonday
	);

	const thisMonthStart = monthStart(year, month);
	const nextMonthStart = monthStart(year, month + 1);

	const quarterMonth = Math.floor(month / 3) * 3;

	const thisQuarterStart =
		monthStart(year, quarterMonth);

	const nextQuarterStart =
		monthStart(year, quarterMonth + 3);

	const thisYearStart = yearStart(year);
	const nextYearStart = yearStart(year + 1);

	switch (value) {
		case 'today':
			return {
				start: today,
				end: addDays(today, 1),
			};

		case 'yesterday':
			return {
				start: addDays(today, -1),
				end: today,
			};

		case 'this_week':
			return {
				start: thisWeekStart,
				end: addDays(thisWeekStart, 7),
			};

		case 'last_week':
			return {
				start: addDays(thisWeekStart, -7),
				end: thisWeekStart,
			};

		case 'this_month':
			return {
				start: thisMonthStart,
				end: nextMonthStart,
			};

		case 'last_month':
			return {
				start: monthStart(year, month - 1),
				end: thisMonthStart,
			};

		case 'this_quarter':
			return {
				start: thisQuarterStart,
				end: nextQuarterStart,
			};

		case 'last_quarter':
			return {
				start: monthStart(year, quarterMonth - 3),
				end: thisQuarterStart,
			};

		case 'this_year':
			return {
				start: thisYearStart,
				end: nextYearStart,
			};

		case 'last_year':
			return {
				start: yearStart(year - 1),
				end: thisYearStart,
			};

		default:
			return null;
	}
}

// ---------------------------------------------------------
// 5. Resolve required date parameters
// ---------------------------------------------------------

let startAt = null;
let endAt = null;

const requiresDateRange =
	requiresStart && requiresEnd;

if (requiresDateRange && !effectiveRange) {
	errors.push({
		code: 'DATE_RANGE_MISSING',
		field: 'date_range',
		message: 'The approved query requires a reporting date range',
	});
}

if (
	requiresDateRange &&
	effectiveRange
) {
	const resolvedRange = resolveRelativeRange(
		effectiveRange,
		new Date()
	);

	if (!resolvedRange) {
		errors.push({
			code: 'RELATIVE_DATE_RANGE_NOT_SUPPORTED',
			field: 'date_range',
			message: `Relative date range ${effectiveRange} is not supported by the execution engine`,
			date_range: effectiveRange,
		});
	}
	else {
		startAt = resolvedRange.start.toISOString();
		endAt = resolvedRange.end.toISOString();
	}
}

// ---------------------------------------------------------
// 6. Build parameter values in approved template order
// ---------------------------------------------------------

const parameterValues = [];

if (errors.length === 0) {
	for (const parameter of allowedParameters) {
		switch (parameter) {
			case 'start_at':
				parameterValues.push(startAt);
				break;

			case 'end_at':
				parameterValues.push(endAt);
				break;

			default:
				errors.push({
					code: 'PARAMETER_VALUE_RESOLUTION_FAILED',
					field: 'allowed_parameters',
					message: `No runtime value resolver exists for ${parameter}`,
					parameter,
				});
		}
	}
}

// ---------------------------------------------------------
// Final result
// ---------------------------------------------------------

const isValid = errors.length === 0;

return {
	...data,

	query_parameters: {
		names: allowedParameters,

		values: isValid
			? parameterValues
			: [],

		named: {
			start_at: startAt,
			end_at: endAt,
		},

		date_range: {
			type: 'relative',
			value: effectiveRange,
			source: rangeSource,
			reporting_timezone: 'UTC',
			start_at: startAt,
			end_at: endAt,
		},

		built_at: new Date().toISOString(),
	},

	parameter_validation: {
		is_valid: isValid,
		validation_status: isValid
			? 'approved'
			: 'rejected',

		errors,
		warnings,

		error_count: errors.length,
		warning_count: warnings.length,

		validation_version: '1.0',
		validated_at: new Date().toISOString(),
	},

	workflow_stage: isValid
		? 'parameters_built'
		: 'parameters_rejected',
};

// REVINT Phase 4
// VAL | Validate Query Result
//
// Purpose:
// Validate the structural result returned by the governed
// reporting query and restore the original request context.
//
// This node does NOT calculate business metrics.
// This node does NOT alter SQL.
// This node validates the database result contract only.

// ---------------------------------------------------------
// 1. Recover authorized request context
// ---------------------------------------------------------

const context =
	$('VAL | Parameters Valid?').item.json;

const resolvedQuery = context.resolved_query ?? {};

const metric =
	Array.isArray(context.metric_catalogue_matches)
		? context.metric_catalogue_matches[0]
		: null;

const errors = [];
const warnings = [];

// ---------------------------------------------------------
// 2. Collect PostgreSQL result rows
// ---------------------------------------------------------

let rows = $input
	.all()
	.map(item => item.json ?? {});

// n8n Always Output Data may return one empty object when
// a query produces zero physical rows.
//
// Normalize that condition to an empty result set.

if (
	rows.length === 1 &&
	rows[0] &&
	typeof rows[0] === 'object' &&
	!Array.isArray(rows[0]) &&
	Object.keys(rows[0]).length === 0
) {
	rows = [];
}

const rowCount = rows.length;

// ---------------------------------------------------------
// 3. Verify upstream authorization state
// ---------------------------------------------------------

if (context.governance_validation?.is_valid !== true) {
	errors.push({
		code: 'GOVERNANCE_NOT_APPROVED',
		field: 'governance_validation',
		message:
			'Query result cannot be accepted because metric governance was not approved',
	});
}

if (context.query_validation?.is_valid !== true) {
	errors.push({
		code: 'QUERY_NOT_APPROVED',
		field: 'query_validation',
		message:
			'Query result cannot be accepted because the SQL template was not approved',
	});
}

if (context.parameter_validation?.is_valid !== true) {
	errors.push({
		code: 'PARAMETERS_NOT_APPROVED',
		field: 'parameter_validation',
		message:
			'Query result cannot be accepted because runtime parameters were not approved',
	});
}

// ---------------------------------------------------------
// 4. Validate result metadata
// ---------------------------------------------------------

const resultType =
	typeof resolvedQuery.result_type === 'string'
		? resolvedQuery.result_type.trim()
		: '';

const supportedResultTypes = new Set([
	'scalar',
	'breakdown',
	'trend',
	'comparison',
	'data_quality',
]);

if (!supportedResultTypes.has(resultType)) {
	errors.push({
		code: 'RESULT_TYPE_NOT_SUPPORTED',
		field: 'resolved_query.result_type',
		message: `Result type ${resultType || 'missing'} is not supported`,
	});
}

// ---------------------------------------------------------
// 5. Determine effective row limit
// ---------------------------------------------------------

const queryMaximumRows =
	Number(resolvedQuery.maximum_rows);

const metricMaximumRows =
	Number(metric?.maximum_rows);

const rowLimits = [];

if (
	Number.isFinite(queryMaximumRows) &&
	queryMaximumRows > 0
) {
	rowLimits.push(queryMaximumRows);
}

if (
	Number.isFinite(metricMaximumRows) &&
	metricMaximumRows > 0
) {
	rowLimits.push(metricMaximumRows);
}

const effectiveMaximumRows =
	rowLimits.length > 0
		? Math.min(...rowLimits)
		: null;

if (effectiveMaximumRows === null) {
	errors.push({
		code: 'RESULT_ROW_LIMIT_MISSING',
		field: 'maximum_rows',
		message:
			'No valid governed maximum row limit is available for this query',
	});
}

if (
	effectiveMaximumRows !== null &&
	rowCount > effectiveMaximumRows
) {
	errors.push({
		code: 'RESULT_ROW_LIMIT_EXCEEDED',
		field: 'query_result',
		message:
			`Query returned ${rowCount} rows but the governed maximum is ${effectiveMaximumRows}`,
		actual_rows: rowCount,
		maximum_rows: effectiveMaximumRows,
	});
}

// ---------------------------------------------------------
// 6. Validate individual rows
// ---------------------------------------------------------

for (let index = 0; index < rows.length; index++) {
	const row = rows[index];

	if (
		row === null ||
		typeof row !== 'object' ||
		Array.isArray(row)
	) {
		errors.push({
			code: 'RESULT_ROW_INVALID',
			field: `query_result.rows[${index}]`,
			message:
				'Every reporting result row must be a JSON object',
		});

		continue;
	}

	if (Object.keys(row).length === 0) {
		errors.push({
			code: 'RESULT_ROW_EMPTY',
			field: `query_result.rows[${index}]`,
			message:
				'Reporting result contains an empty row object',
		});
	}
}

// ---------------------------------------------------------
// 7. Result-type structural rules
// ---------------------------------------------------------

if (resultType === 'scalar') {

	if (rowCount === 0) {
		errors.push({
			code: 'SCALAR_RESULT_MISSING',
			field: 'query_result',
			message:
				'Scalar reporting queries must return exactly one result row',
		});
	}

	if (rowCount > 1) {
		errors.push({
			code: 'SCALAR_RESULT_MULTIPLE_ROWS',
			field: 'query_result',
			message:
				`Scalar reporting query returned ${rowCount} rows instead of exactly one`,
			actual_rows: rowCount,
		});
	}
}

// Empty breakdown/trend results are not automatically errors.
// A valid governed query may legitimately have no matching data.

if (
	rowCount === 0 &&
	[
		'breakdown',
		'trend',
		'comparison',
	].includes(resultType)
) {
	warnings.push({
		code: 'RESULT_SET_EMPTY',
		field: 'query_result',
		message:
			'The approved query completed successfully but returned no matching rows',
	});
}

// ---------------------------------------------------------
// 8. Final validation
// ---------------------------------------------------------

const isValid = errors.length === 0;

return [
	{
		json: {
			...context,

			query_result: {
				query_key:
					resolvedQuery.query_key ?? null,

				result_type:
					resultType || null,

				rows,

				row_count: rowCount,

				maximum_rows:
					effectiveMaximumRows,

				executed_with:
					'PG | Reporting RO',

				received_at:
					new Date().toISOString(),
			},

			result_validation: {
				is_valid: isValid,

				validation_status:
					isValid
						? 'approved'
						: 'rejected',

				errors,
				warnings,

				error_count:
					errors.length,

				warning_count:
					warnings.length,

				validation_version:
					'1.0',

				validated_at:
					new Date().toISOString(),
			},

			workflow_stage:
				isValid
					? 'result_validated'
					: 'result_rejected',
		},
	},
];

const data = $json;

const errors = [];
const warnings = [];

// ---------------------------------------------------------
// 1. Verify upstream authorization boundaries
// ---------------------------------------------------------

if (data.governance_validation?.is_valid !== true) {
	errors.push({
		code: 'GOVERNANCE_NOT_APPROVED',
		message: 'Governance validation must be approved before analysis.'
	});
}

if (data.query_validation?.is_valid !== true) {
	errors.push({
		code: 'QUERY_NOT_APPROVED',
		message: 'Approved-query validation must pass before analysis.'
	});
}

if (data.parameter_validation?.is_valid !== true) {
	errors.push({
		code: 'PARAMETERS_NOT_APPROVED',
		message: 'Runtime parameters must be approved before analysis.'
	});
}

if (data.result_validation?.is_valid !== true) {
	errors.push({
		code: 'RESULT_NOT_APPROVED',
		message: 'Query result validation must pass before analysis.'
	});
}

// ---------------------------------------------------------
// 2. Resolve governed metric
// Phase 5 v1 currently supports one resolved metric per request.
// ---------------------------------------------------------

const metricMatches = Array.isArray(data.metric_catalogue_matches)
	? data.metric_catalogue_matches
	: [];

if (metricMatches.length !== 1) {
	errors.push({
		code: 'ANALYSIS_METRIC_CARDINALITY_INVALID',
		message: `Phase 5 v1 requires exactly one governed metric. Received ${metricMatches.length}.`
	});
}

const metric = metricMatches[0] ?? null;

// ---------------------------------------------------------
// 3. Validate query result contract
// ---------------------------------------------------------

const queryResult = data.query_result ?? null;

if (!queryResult || typeof queryResult !== 'object') {
	errors.push({
		code: 'QUERY_RESULT_MISSING',
		message: 'Validated query_result is required for analysis.'
	});
}

const supportedResultTypes = [
	'scalar',
	'breakdown',
	'trend',
	'comparison',
	'data_quality'
];

if (
	queryResult?.result_type &&
	!supportedResultTypes.includes(queryResult.result_type)
) {
	errors.push({
		code: 'RESULT_TYPE_UNSUPPORTED_FOR_ANALYSIS',
		message: `Unsupported result type: ${queryResult.result_type}`
	});
}

const rows = Array.isArray(queryResult?.rows)
	? queryResult.rows
	: [];

if (
	typeof queryResult?.row_count === 'number' &&
	queryResult.row_count !== rows.length
) {
	errors.push({
		code: 'RESULT_ROW_COUNT_MISMATCH',
		message: `query_result.row_count is ${queryResult.row_count}, but ${rows.length} row(s) are present.`
	});
}

// ---------------------------------------------------------
// 4. Build reporting-period context
// ---------------------------------------------------------

const dateRange = data.query_parameters?.date_range ?? {};

const reportingPeriod = {
	type: dateRange.type ?? null,
	value: dateRange.value ?? null,
	source: dateRange.source ?? null,
	reporting_timezone: dateRange.reporting_timezone ?? 'UTC',
	start_at: dateRange.start_at ?? null,
	end_at: dateRange.end_at ?? null
};

// Snapshot metrics may intentionally have no start/end date.
if (!reportingPeriod.start_at || !reportingPeriod.end_at) {
	warnings.push({
		code: 'ANALYSIS_PERIOD_BOUNDARY_ABSENT',
		message: 'Reporting period does not contain both start_at and end_at. This may be valid for snapshot metrics.'
	});
}

// ---------------------------------------------------------
// 5. Build AI-safe business context
// IMPORTANT:
// No SQL template, database name, table name, or raw query
// is copied into this object.
// ---------------------------------------------------------

const analysisContext = {
	request: {
		request_id: data.request_id,
		correlation_id: data.correlation_id,
		question: data.question,
		channel: data.channel,
		requester_name: data.requester_name ?? null
	},

	metric: metric
		? {
			metric_id: metric.metric_id,
			metric_key: metric.metric_key,
			metric_name: metric.metric_name,
			description: metric.description,
			business_definition: metric.business_definition,
			default_visualization: metric.default_visualization
		}
		: null,

	intent: {
		intent: data.parsed_intent?.intent ?? null,
		dimensions: data.parsed_intent?.dimensions ?? [],
		filters: data.parsed_intent?.filters ?? [],
		comparison: data.parsed_intent?.comparison ?? null,
		requested_visualization:
			data.parsed_intent?.visualization ?? null
	},

	reporting_period: reportingPeriod,

	result: {
		query_key: queryResult?.query_key ?? null,
		result_type: queryResult?.result_type ?? null,
		row_count: queryResult?.row_count ?? rows.length,
		rows
	},

	authorization: {
		governance_approved: data.governance_validation?.is_valid === true,
		query_approved: data.query_validation?.is_valid === true,
		parameters_approved: data.parameter_validation?.is_valid === true,
		result_approved: data.result_validation?.is_valid === true,
		executed_with: queryResult?.executed_with ?? null
	},

	context_version: '1.0',
	built_at: new Date().toISOString()
};

// ---------------------------------------------------------
// 6. Final preparation result
// ---------------------------------------------------------

const isValid = errors.length === 0;

return {
	...data,

	analysis_context: analysisContext,

	analysis_preparation: {
		is_valid: isValid,
		validation_status: isValid
			? 'approved'
			: 'rejected',

		errors,
		warnings,

		error_count: errors.length,
		warning_count: warnings.length,

		validation_version: '1.0',
		validated_at: new Date().toISOString()
	},

	workflow_stage: isValid
		? 'analysis_context_built'
		: 'analysis_context_rejected'
};

const data = $json;
const context = data.analysis_context ?? {};

const errors = [];
const warnings = [];

const metric = context.metric ?? {};
const result = context.result ?? {};
const rows = Array.isArray(result.rows)
	? result.rows
	: [];

const resultType = result.result_type ?? null;

// ---------------------------------------------------------
// 1. Verify analysis authorization
// ---------------------------------------------------------

if (data.analysis_preparation?.is_valid !== true) {
	errors.push({
		code: 'ANALYSIS_CONTEXT_NOT_APPROVED',
		message: 'Analysis context must be approved before business facts are derived.'
	});
}

if (context.authorization?.governance_approved !== true) {
	errors.push({
		code: 'GOVERNANCE_AUTHORIZATION_MISSING',
		message: 'Governance authorization is missing.'
	});
}

if (context.authorization?.query_approved !== true) {
	errors.push({
		code: 'QUERY_AUTHORIZATION_MISSING',
		message: 'Query authorization is missing.'
	});
}

if (context.authorization?.parameters_approved !== true) {
	errors.push({
		code: 'PARAMETER_AUTHORIZATION_MISSING',
		message: 'Parameter authorization is missing.'
	});
}

if (context.authorization?.result_approved !== true) {
	errors.push({
		code: 'RESULT_AUTHORIZATION_MISSING',
		message: 'Result authorization is missing.'
	});
}

// ---------------------------------------------------------
// 2. Supported result contracts
// ---------------------------------------------------------

const supportedResultTypes = [
	'scalar',
	'breakdown',
	'trend',
	'comparison',
	'data_quality'
];

if (!supportedResultTypes.includes(resultType)) {
	errors.push({
		code: 'ANALYSIS_RESULT_TYPE_UNSUPPORTED',
		message: `Unsupported result type for deterministic analysis: ${resultType}`
	});
}

// ---------------------------------------------------------
// 3. Generic row validation
// ---------------------------------------------------------

if (!Array.isArray(result.rows)) {
	errors.push({
		code: 'ANALYSIS_ROWS_MISSING',
		message: 'Validated result rows are required.'
	});
}

if (
	typeof result.row_count === 'number' &&
	result.row_count !== rows.length
) {
	errors.push({
		code: 'ANALYSIS_ROW_COUNT_MISMATCH',
		message: `Declared row_count ${result.row_count} does not match ${rows.length} row(s).`
	});
}

// ---------------------------------------------------------
// 4. Derive deterministic business facts
// ---------------------------------------------------------

let facts = {
	metric_id: metric.metric_id ?? null,
	metric_key: metric.metric_key ?? null,
	metric_name: metric.metric_name ?? null,
	result_type: resultType,
	reporting_period: context.reporting_period ?? null,
	primary_value: null,
	supporting_values: {},
	breakdown: [],
	trend: [],
	comparison: null,
	data_quality: null
};

// ---------------------------------------------------------
// Scalar analysis
// ---------------------------------------------------------

if (resultType === 'scalar') {

	if (rows.length !== 1) {
		errors.push({
			code: 'SCALAR_ANALYSIS_REQUIRES_ONE_ROW',
			message: `Scalar analysis requires exactly one row. Received ${rows.length}.`
		});
	} else {

		const row = rows[0] ?? {};

		const numericEntries = Object.entries(row)
			.map(([key, value]) => ({
				key,
				raw_value: value,
				numeric_value:
					value !== null &&
					value !== '' &&
					!Number.isNaN(Number(value))
						? Number(value)
						: null
			}));

		const primary =
			numericEntries.find(
				entry => entry.key === metric.metric_key
			) ??
			numericEntries.find(
				entry => entry.numeric_value !== null
			) ??
			null;

		if (!primary) {
			errors.push({
				code: 'SCALAR_PRIMARY_VALUE_NOT_FOUND',
				message: 'No numeric scalar value could be derived from the validated result.'
			});
		} else {

			facts.primary_value = {
				field: primary.key,
				value: primary.numeric_value,
				raw_value: primary.raw_value
			};

			for (const entry of numericEntries) {
				if (entry.key !== primary.key) {
					facts.supporting_values[entry.key] =
						entry.numeric_value !== null
							? entry.numeric_value
							: entry.raw_value;
				}
			}
		}
	}
}

// ---------------------------------------------------------
// Breakdown analysis
// ---------------------------------------------------------

if (resultType === 'breakdown') {

	facts.breakdown = rows;

	if (rows.length === 0) {
		warnings.push({
			code: 'BREAKDOWN_RESULT_EMPTY',
			message: 'Breakdown result contains no rows.'
		});
	}
}

// ---------------------------------------------------------
// Trend analysis
// ---------------------------------------------------------

if (resultType === 'trend') {

	facts.trend = rows;

	if (rows.length === 0) {
		warnings.push({
			code: 'TREND_RESULT_EMPTY',
			message: 'Trend result contains no rows.'
		});
	}
}

// ---------------------------------------------------------
// Comparison analysis
// ---------------------------------------------------------

if (resultType === 'comparison') {

	facts.comparison = {
		rows
	};

	if (rows.length === 0) {
		warnings.push({
			code: 'COMPARISON_RESULT_EMPTY',
			message: 'Comparison result contains no rows.'
		});
	}
}

// ---------------------------------------------------------
// Data-quality analysis
// ---------------------------------------------------------

if (resultType === 'data_quality') {

	facts.data_quality = {
		rows
	};

	if (rows.length === 0) {
		warnings.push({
			code: 'DATA_QUALITY_RESULT_EMPTY',
			message: 'Data-quality result contains no rows.'
		});
	}
}

// ---------------------------------------------------------
// 5. Build AI-safe management input
// ---------------------------------------------------------

const managementInput = {
	manager_question:
		context.request?.question ?? null,

	metric: {
		metric_id: metric.metric_id ?? null,
		metric_key: metric.metric_key ?? null,
		metric_name: metric.metric_name ?? null,
		description: metric.description ?? null,
		business_definition:
			metric.business_definition ?? null
	},

	reporting_period:
		context.reporting_period ?? null,

	facts,

	requested_visualization:
		context.intent?.requested_visualization ?? null,

	input_version: '1.0',
	prepared_at: new Date().toISOString()
};

// ---------------------------------------------------------
// 6. Final deterministic analysis result
// ---------------------------------------------------------

const isValid = errors.length === 0;

return {
	...data,

	analysis_facts: facts,

	management_summary_input:
		isValid
			? managementInput
			: null,

	analysis_validation: {
		is_valid: isValid,

		validation_status:
			isValid
				? 'approved'
				: 'rejected',

		errors,
		warnings,

		error_count: errors.length,
		warning_count: warnings.length,

		analysis_version: '1.0',
		validated_at: new Date().toISOString()
	},

	workflow_stage:
		isValid
			? 'business_facts_derived'
			: 'business_analysis_rejected'
};

const data = $json;

const errors = [];
const warnings = [];

const output = data.output;
const sourceInput = data.management_summary_input ?? null;

// ---------------------------------------------------------
// 1. Verify upstream authorization
// ---------------------------------------------------------

if (data.analysis_validation?.is_valid !== true) {
	errors.push({
		code: 'BUSINESS_ANALYSIS_NOT_APPROVED',
		message: 'Business analysis must be approved before management-summary validation.'
	});
}

if (!data.request_id) {
	errors.push({
		code: 'REQUEST_ID_MISSING',
		message: 'request_id is required for management-summary traceability.'
	});
}

if (!data.correlation_id) {
	errors.push({
		code: 'CORRELATION_ID_MISSING',
		message: 'correlation_id is required for management-summary traceability.'
	});
}

if (!sourceInput || typeof sourceInput !== 'object') {
	errors.push({
		code: 'MANAGEMENT_SUMMARY_INPUT_MISSING',
		message: 'Approved management_summary_input is required.'
	});
}

// ---------------------------------------------------------
// 2. Verify AI output object
// ---------------------------------------------------------

if (!output || typeof output !== 'object' || Array.isArray(output)) {
	errors.push({
		code: 'MANAGEMENT_SUMMARY_OUTPUT_MISSING',
		message: 'Structured AI management-summary output is required.'
	});
}

// ---------------------------------------------------------
// 3. Required output contract
// ---------------------------------------------------------

const requiredFields = [
	'headline',
	'summary',
	'key_facts',
	'management_interpretation',
	'recommended_action',
	'limitations'
];

if (output && typeof output === 'object' && !Array.isArray(output)) {

	const outputKeys = Object.keys(output);

	for (const field of requiredFields) {
		if (!outputKeys.includes(field)) {
			errors.push({
				code: 'MANAGEMENT_SUMMARY_FIELD_MISSING',
				message: `Required management-summary field is missing: ${field}`
			});
		}
	}

	const unexpectedFields = outputKeys.filter(
		key => !requiredFields.includes(key)
	);

	if (unexpectedFields.length > 0) {
		errors.push({
			code: 'MANAGEMENT_SUMMARY_UNEXPECTED_FIELDS',
			message: `Unexpected management-summary field(s): ${unexpectedFields.join(', ')}`
		});
	}
}

// ---------------------------------------------------------
// 4. String validation
// ---------------------------------------------------------

function validateRequiredString(value, field, maxLength) {

	if (typeof value !== 'string' || value.trim().length === 0) {
		errors.push({
			code: 'MANAGEMENT_SUMMARY_INVALID_STRING',
			message: `${field} must be a non-empty string.`
		});
		return;
	}

	if (value.length > maxLength) {
		errors.push({
			code: 'MANAGEMENT_SUMMARY_STRING_TOO_LONG',
			message: `${field} exceeds the maximum length of ${maxLength}.`
		});
	}
}

if (output) {
	validateRequiredString(output.headline, 'headline', 160);
	validateRequiredString(output.summary, 'summary', 1200);
}

// ---------------------------------------------------------
// 5. Array validation
// ---------------------------------------------------------

function validateStringArray(value, field, minItems, maxItems) {

	if (!Array.isArray(value)) {
		errors.push({
			code: 'MANAGEMENT_SUMMARY_INVALID_ARRAY',
			message: `${field} must be an array.`
		});
		return;
	}

	if (value.length < minItems || value.length > maxItems) {
		errors.push({
			code: 'MANAGEMENT_SUMMARY_ARRAY_SIZE_INVALID',
			message: `${field} must contain between ${minItems} and ${maxItems} item(s).`
		});
	}

	value.forEach((item, index) => {

		if (
			typeof item !== 'string' ||
			item.trim().length === 0
		) {
			errors.push({
				code: 'MANAGEMENT_SUMMARY_ARRAY_ITEM_INVALID',
				message: `${field}[${index}] must be a non-empty string.`
			});
		}

		if (
			typeof item === 'string' &&
			item.length > 300
		) {
			errors.push({
				code: 'MANAGEMENT_SUMMARY_ARRAY_ITEM_TOO_LONG',
				message: `${field}[${index}] exceeds 300 characters.`
			});
		}
	});
}

if (output) {
	validateStringArray(output.key_facts, 'key_facts', 1, 10);
	validateStringArray(output.limitations, 'limitations', 0, 10);
}

// ---------------------------------------------------------
// 6. Nullable interpretation / recommendation
// ---------------------------------------------------------

function validateNullableString(value, field, maxLength) {

	if (value === null) {
		return;
	}

	if (typeof value !== 'string' || value.trim().length === 0) {
		errors.push({
			code: 'MANAGEMENT_SUMMARY_NULLABLE_FIELD_INVALID',
			message: `${field} must be a non-empty string or null.`
		});
		return;
	}

	if (value.length > maxLength) {
		errors.push({
			code: 'MANAGEMENT_SUMMARY_NULLABLE_FIELD_TOO_LONG',
			message: `${field} exceeds the maximum length of ${maxLength}.`
		});
	}
}

if (output) {
	validateNullableString(
		output.management_interpretation,
		'management_interpretation',
		800
	);

	validateNullableString(
		output.recommended_action,
		'recommended_action',
		800
	);
}

// ---------------------------------------------------------
// 7. Build text representations
// ---------------------------------------------------------

const sourceText = sourceInput
	? JSON.stringify(sourceInput)
	: '';

const outputText = output
	? JSON.stringify(output)
	: '';

// ---------------------------------------------------------
// 8. Reject unsupported currency / percentage units
// ---------------------------------------------------------

const controlledUnits = [
	'$',
	'£',
	'€',
	'¥',
	'₹',
	'%',
	'USD',
	'GBP',
	'EUR',
	'NGN',
	'JPY',
	'CAD',
	'AUD'
];

for (const unit of controlledUnits) {

	const outputHasUnit =
		outputText.toUpperCase().includes(unit.toUpperCase());

	const sourceHasUnit =
		sourceText.toUpperCase().includes(unit.toUpperCase());

	if (outputHasUnit && !sourceHasUnit) {
		errors.push({
			code: 'UNSUPPORTED_UNIT_INTRODUCED',
			message: `AI output introduced unsupported unit or currency: ${unit}`
		});
	}
}

// ---------------------------------------------------------
// 9. Reject technical implementation leakage
// ---------------------------------------------------------

const forbiddenTechnicalPatterns = [
	/\bSQL\b/i,
	/\bPostgreSQL\b/i,
	/\bPostgres\b/i,
	/\bdatabase\b/i,
	/\bschema\b/i,
	/\bcredential\b/i,
	/\bquery template\b/i,
	/\bworkflow id\b/i,
	/\bexecution id\b/i
];

for (const pattern of forbiddenTechnicalPatterns) {

	if (pattern.test(outputText)) {
		errors.push({
			code: 'TECHNICAL_IMPLEMENTATION_LEAKAGE',
			message: `Management summary contains prohibited technical implementation language: ${pattern}`
		});
	}
}

// ---------------------------------------------------------
// 10. Numeric grounding check
// ---------------------------------------------------------

function extractNumbers(text) {

	const matches =
		String(text).match(/[-+]?\d[\d,]*(?:\.\d+)?/g) ?? [];

	return matches
		.map(value => Number(value.replace(/,/g, '')))
		.filter(value => Number.isFinite(value));
}

const allowedNumbers = extractNumbers(sourceText);
const generatedNumbers = extractNumbers(outputText);

for (const generatedValue of generatedNumbers) {

	const grounded = allowedNumbers.some(
		allowedValue =>
			Math.abs(allowedValue - generatedValue) < 0.0000001
	);

	if (!grounded) {
		errors.push({
			code: 'UNGROUNDED_NUMERIC_VALUE',
			message: `AI output contains numeric value not present in approved management input: ${generatedValue}`
		});
	}
}

// ---------------------------------------------------------
// 11. Final validation result
// ---------------------------------------------------------

const isValid = errors.length === 0;

return {
	...data,

	management_summary:
		isValid
			? output
			: null,

	management_summary_validation: {
		is_valid: isValid,

		validation_status:
			isValid
				? 'approved'
				: 'rejected',

		errors,
		warnings,

		error_count: errors.length,
		warning_count: warnings.length,

		validation_version: '1.0',
		validated_at: new Date().toISOString()
	},

	workflow_stage:
		isValid
			? 'management_summary_validated'
			: 'management_summary_rejected'
};

