];

if (!allowedPresentationTypes.includes(presentationType)) {
	errors.push({
		code: 'APPROVED_REPORT_PRESENTATION_TYPE_UNSUPPORTED',
		message:
			`Unsupported approved-report presentation type: ${presentationType}`
