const data = $json;

const errors = [];
const warnings = [];

const chartPayload = data.chart_payload ?? null;

// ---------------------------------------------------------
// 1. Enforce upstream chart authorization
// ---------------------------------------------------------

if (data.presentation_resolution?.is_valid !== true) {
	errors.push({
		code: 'PRESENTATION_NOT_AUTHORIZED',
		message:
			'Approved presentation resolution is required before chart render preparation.'
	});
}

if (data.chart_build?.is_valid !== true) {
	errors.push({
		code: 'CHART_PAYLOAD_NOT_AUTHORIZED',
		message:
			'Approved chart payload is required before chart render preparation.'
	});
}

if (!chartPayload) {
	errors.push({
		code: 'CHART_PAYLOAD_MISSING',
		message:
			'chart_payload is required before building a chart render contract.'
	});
}

if (
	data.report_presentation?.presentation_type !== 'chart'
) {
	errors.push({
		code: 'PRESENTATION_TYPE_NOT_CHART',
		message:
			'Chart render preparation accepts only presentation_type = chart.'
	});
}

// ---------------------------------------------------------
// 2. Enforce request trace identity
// ---------------------------------------------------------

if (
	chartPayload?.request_id &&
	data.request_id &&
	chartPayload.request_id !== data.request_id
) {
	errors.push({
		code: 'CHART_RENDER_REQUEST_ID_MISMATCH',
		message:
			'chart_payload request_id does not match workflow request_id.'
	});
}

if (
	chartPayload?.correlation_id &&
	data.correlation_id &&
	chartPayload.correlation_id !== data.correlation_id
) {
	errors.push({
		code: 'CHART_RENDER_CORRELATION_ID_MISMATCH',
		message:
			'chart_payload correlation_id does not match workflow correlation_id.'
	});
}

// ---------------------------------------------------------
// 3. Approved deterministic render profiles
// ---------------------------------------------------------

const metricKey =
	chartPayload?.metric?.metric_key ?? null;

const renderProfiles = {
	pipeline_by_sales_rep: {
		required_result_type: 'breakdown',
		required_chart_type: 'bar_chart',

		render_chart_type: 'bar',

		x_key: 'sales_rep',
		x_label: 'Sales Rep',

		series: [
			{
				data_key: 'pipeline_value',
				label: 'Pipeline Value',
				value_type: 'currency',
				value_format: 'compact'
			}
		],

		supporting_fields: [
			'deal_count'
		]
	}
};

const profile =
	renderProfiles[metricKey] ?? null;

if (!profile) {
	errors.push({
		code: 'CHART_RENDER_PROFILE_NOT_APPROVED',
		message:
			`No approved chart render profile exists for metric_key ${metricKey}.`
	});
}

// ---------------------------------------------------------
// 4. Validate profile against governed chart payload
// ---------------------------------------------------------

if (
	profile &&
	chartPayload?.result_type !== profile.required_result_type
) {
	errors.push({
		code: 'CHART_RENDER_RESULT_TYPE_MISMATCH',
		message:
			`Expected result_type ${profile.required_result_type} but received ${chartPayload?.result_type}.`
	});
}

if (
	profile &&
	chartPayload?.chart_type !== profile.required_chart_type
) {
	errors.push({
		code: 'CHART_RENDER_TYPE_MISMATCH',
		message:
			`Expected chart_type ${profile.required_chart_type} but received ${chartPayload?.chart_type}.`
	});
}

const sourceRows =
	Array.isArray(chartPayload?.data?.rows)
		? chartPayload.data.rows
		: [];

if (!Array.isArray(chartPayload?.data?.rows)) {
	errors.push({
		code: 'CHART_RENDER_ROWS_MISSING',
		message:
			'chart_payload.data.rows must be an array.'
	});
}

// ---------------------------------------------------------
// 5. Build deterministic render rows
// ---------------------------------------------------------

const renderRows = [];

if (profile) {
	for (let index = 0; index < sourceRows.length; index++) {

		const row = sourceRows[index];

		const categoryValue =
			row?.[profile.x_key];

		if (
			categoryValue === null ||
			categoryValue === undefined ||
			String(categoryValue).trim() === ''
		) {
			errors.push({
				code: 'CHART_RENDER_CATEGORY_MISSING',
				message:
					`Row ${index + 1} is missing required category field ${profile.x_key}.`
			});

			continue;
		}

		const renderRow = {
			[profile.x_key]:
				String(categoryValue)
		};

		for (const series of profile.series) {

			const rawValue =
				row?.[series.data_key];

			const numericValue =
				Number(rawValue);

			if (!Number.isFinite(numericValue)) {
				errors.push({
					code: 'CHART_RENDER_VALUE_INVALID',
					message:
						`Row ${index + 1} contains a non-numeric value for ${series.data_key}.`
				});

				continue;
			}

			renderRow[series.data_key] =
				numericValue;
		}

		for (const field of profile.supporting_fields) {
			if (row?.[field] !== undefined) {
				renderRow[field] =
					row[field];
			}
		}

		renderRows.push(renderRow);
	}
}

if (sourceRows.length === 0) {
	warnings.push({
		code: 'CHART_RENDER_EMPTY_DATASET',
		message:
			'Approved chart result contains no rows. Delivery should use an empty-state presentation.'
	});
}

// ---------------------------------------------------------
// 6. Build delivery-neutral render contract
// ---------------------------------------------------------

const isValid =
	errors.length === 0;

const chartRenderContract =
	isValid
		? {
			request_id:
				data.request_id ?? null,

			correlation_id:
				data.correlation_id ?? null,

			contract_type:
				'governed_chart_render',

			renderer_family:
				'delivery_adapter',

			metric: {
				metric_id:
					chartPayload.metric?.metric_id ?? null,

				metric_key:
					chartPayload.metric?.metric_key ?? null,

				metric_name:
					chartPayload.metric?.metric_name ?? null
			},

			title:
				chartPayload.title ?? null,

			description:
				chartPayload.summary ?? null,

			chart_type:
				profile.render_chart_type,

			x_key:
				profile.x_key,

			x_label:
				profile.x_label,

			series:
				profile.series,

			supporting_fields:
				profile.supporting_fields,

			data:
				renderRows,

			row_count:
				renderRows.length,

			reporting_period:
				chartPayload.reporting_period ?? null,

			delivery_neutral:
				true,

			rendering_status:
				'render_ready',

			rendered_asset:
				null,

			contract_version:
				'1.0',

			prepared_at:
				new Date().toISOString()
		}
		: null;

// ---------------------------------------------------------
// 7. Enrich chart payload
// ---------------------------------------------------------

const enrichedChartPayload =
	isValid
		? {
			...chartPayload,

			render_strategy: {
				...(chartPayload.render_strategy ?? {}),

				data_contract:
					'governed_rows',

				rendering_status:
					'render_ready',

				delivery_neutral:
					true,

				render_contract:
					'governed_chart_render'
			},

			render_contract:
				chartRenderContract
		}
		: chartPayload;

// ---------------------------------------------------------
// 8. Return preparation state
// ---------------------------------------------------------

return {
	...data,

	chart_payload:
		enrichedChartPayload,

	chart_render_contract:
		chartRenderContract,

	chart_render_preparation: {
		is_valid:
			isValid,

		preparation_status:
			isValid
				? 'approved'
				: 'rejected',

		metric_key:
			metricKey,

		chart_type:
			chartPayload?.chart_type ?? null,

		render_chart_type:
			profile?.render_chart_type ?? null,

		row_count:
			renderRows.length,

		errors,
		warnings,

		error_count:
			errors.length,

		warning_count:
			warnings.length,

		preparation_version:
			'1.0',

		prepared_at:
			new Date().toISOString()
	},

	workflow_stage:
		isValid
