};

const data = $json;

const errors = [];
const warnings = [];

const artifact =
	data.approved_report_artifact ?? null;

const assembly =
	data.approved_report_assembly ?? null;

// ---------------------------------------------------------
// 1. Enforce final Phase 6 authorization
// ---------------------------------------------------------

if (assembly?.is_valid !== true) {
	errors.push({
		code: 'REPORT_ARTIFACT_NOT_AUTHORIZED',
		message:
			'An approved report artifact is required before delivery routing.'
	});
}

if (!artifact) {
	errors.push({
		code: 'APPROVED_REPORT_ARTIFACT_MISSING',
		message:
			'approved_report_artifact is required before delivery routing.'
	});
}

// ---------------------------------------------------------
// 2. Enforce request trace identity
// ---------------------------------------------------------

if (
	artifact?.request_id &&
	data.request_id &&
	artifact.request_id !== data.request_id
) {
	errors.push({
		code: 'DELIVERY_REQUEST_ID_MISMATCH',
		message:
			'Approved report artifact request_id does not match workflow request_id.'
	});
