) {
	errors.push({
		code: 'DELIVERY_CORRELATION_ID_MISMATCH',
		message:
			'Approved report artifact correlation_id does not match workflow correlation_id.'
	});
}

// ---------------------------------------------------------
// 3. Validate presentation type
// ---------------------------------------------------------

const presentationType =
	artifact?.presentation_type ?? null;

const allowedPresentationTypes = [
	'kpi_card',
	'chart',
	'table'
];

if (
	!allowedPresentationTypes.includes(
		presentationType
	)
) {
	errors.push({
		code: 'DELIVERY_PRESENTATION_TYPE_NOT_ALLOWED',
		message:
			`Presentation type ${presentationType} is not approved for delivery routing.`
	});
}

// ---------------------------------------------------------
// 4. Resolve explicit delivery request
// ---------------------------------------------------------

const rawRequestedDelivery =
	artifact?.requested_delivery ??
	data.parsed_intent?.delivery ??
	null;

const requestedDelivery =
	typeof rawRequestedDelivery === 'string'
		? rawRequestedDelivery
				.trim()
				.toLowerCase()
		: null;

const allowedExplicitDeliveries = [
	'slack',
	'email',
	'api'
];

if (
	requestedDelivery &&
	!allowedExplicitDeliveries.includes(
		requestedDelivery
	)
) {
	errors.push({
		code: 'DELIVERY_CHANNEL_NOT_ALLOWED',
		message:
			`Requested delivery channel ${requestedDelivery} is not approved.`
	});
}

// ---------------------------------------------------------
// 5. Resolve fallback from trusted request channel
// ---------------------------------------------------------

const sourceChannel =
	String(
		artifact?.channel ??
		data.channel ??
		''
	)
	.trim()
	.toLowerCase();

const sourceChannelRoutes = {
	slack: 'slack',
	email: 'email',
	api: 'api',
	form: 'form',
	manual: 'manual_preview'
};

let resolvedDeliveryChannel =
	requestedDelivery ?? null;

let resolutionSource =
	requestedDelivery
		? 'manager_request'
		: 'request_channel';

if (
	!resolvedDeliveryChannel &&
	sourceChannel
) {
	resolvedDeliveryChannel =
		sourceChannelRoutes[sourceChannel] ??
		null;
}

if (!resolvedDeliveryChannel) {
	errors.push({
		code: 'DELIVERY_ROUTE_NOT_RESOLVED',
		message:
			'No approved delivery route could be resolved from the request.'
	});
}

// ---------------------------------------------------------
// 6. Approved delivery adapter profiles
// ---------------------------------------------------------

const deliveryProfiles = {
	slack: {
		adapter_type:
			'slack_message',

		execution_mode:
			'external_delivery',

		requires_destination:
			true,

		destination_resolution:
			'trusted_configuration'
	},

	email: {
		adapter_type:
			'email_message',

		execution_mode:
			'external_delivery',

		requires_destination:
			true,

		destination_resolution:
			'trusted_configuration'
	},

	api: {
		adapter_type:
			'api_response',

		execution_mode:
			'request_response',

		requires_destination:
			false,

		destination_resolution:
			'request_context'
	},

	form: {
		adapter_type:
			'form_response',

		execution_mode:
			'request_response',

		requires_destination:
			false,

		destination_resolution:
			'request_context'
	},

	manual_preview: {
		adapter_type:
			'manual_preview',

		execution_mode:
			'internal_preview',

		requires_destination:
			false,

		destination_resolution:
			'none'
	}
};

const deliveryProfile =
	deliveryProfiles[
		resolvedDeliveryChannel
	] ?? null;

if (!deliveryProfile) {
	errors.push({
		code: 'DELIVERY_ADAPTER_NOT_APPROVED',
		message:
			`No approved delivery adapter exists for ${resolvedDeliveryChannel}.`
	});
}

// ---------------------------------------------------------
// 7. Chart delivery boundary
// ---------------------------------------------------------

const requiresChartRenderContract =
	presentationType === 'chart';

const chartRenderContract =
	artifact?.presentation_payload
		?.render_contract ?? null;

const chartRenderReady =
	artifact?.presentation_payload
		?.render_strategy
