// 8. Build deterministic delivery route
// ---------------------------------------------------------

const isValid =
	errors.length === 0;

const deliveryRoute =
	isValid
		? {
			request_id:
				data.request_id ?? null,

			correlation_id:
				data.correlation_id ?? null,

			source_channel:
				sourceChannel || null,

			requested_delivery:
